def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    units = int(supply // WATER_REQ)
    if units < 1:
        units = 1

    prev_bids = []
    prev_urgent_bids = []
    opp_count = 0
    urgent_opp_count = 0

    for opp in alive_opponents:
        opp_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid = float(prev['bid'])
            prev_bids.append(bid)
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                prev_urgent_bids.append(bid)
                urgent_opp_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    highest_urgent = max(prev_urgent_bids) if prev_urgent_bids else highest_prev

    contested = opp_count + 1 > units
    very_tight = units <= 1
    tight = units <= 2
    danger = hp <= 3 or no_water_days >= 1
    critical = hp <= 2 or no_water_days >= 2

    if opp_count == 0:
        return float(min(budget, 18.0 if not danger else 42.0))

    if critical:
        target = max(0.92 * DAILY_SALARY, highest_urgent + 2.0)
        if very_tight:
            target = max(target, highest_prev + 4.0)
        return float(min(budget, target))

    if danger:
        if contested:
            target = max(0.78 * DAILY_SALARY, highest_prev + 1.5)
            if very_tight:
                target = max(target, 0.9 * DAILY_SALARY)
        else:
            target = max(0.58 * DAILY_SALARY, avg_prev + 1.0)
        return float(min(budget, target))

    if very_tight:
        if highest_prev >= 75:
            target = max(34.0, highest_prev - 8.0)
        else:
            target = max(52.0, highest_prev + 1.5)
        return float(min(budget, target))

    if tight:
        if highest_prev >= 80:
            target = 31.0
        else:
            target = max(43.0, avg_prev + 1.0)
        return float(min(budget, target))

    if contested:
        if highest_prev >= 80:
            target = 26.0
        else:
            target = max(32.0, avg_prev * 0.72)
        return float(min(budget, target))

    target = 22.0
    if day >= 8 and hp >= 5:
        target = 18.0
    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    # --- Bidding Strategy ---

    # 1. Survival Bids (High Priority)
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    if my_status['no_water_days'] > 0:
        return min(my_status['budget'], DAILY_SALARY * 0.9)

    # 2. Reactive Bids based on Opponent's Last Day Behavior
    if highest_prev_bid >= DAILY_SALARY * 0.8:
        if my_status['hp'] > 5:
            return min(my_status['budget'], highest_prev_bid + 1, DAILY_SALARY * 0.88)
        else:
            return min(my_status['budget'], highest_prev_bid + 5, DAILY_SALARY * 0.92)

    if highest_prev_bid > DAILY_SALARY * 0.4:
        target_bid = max(DAILY_SALARY * 0.55, highest_prev_bid + 1)
        # If supply is tight and multiple opponents, increase bid slightly
        if current_supply < WATER_REQ * 1.5 and num_alive_opponents > 1:
            target_bid = max(target_bid, DAILY_SALARY * 0.7)
        return min(my_status['budget'], target_bid, DAILY_SALARY * 0.8)

    # 3. Default Bid
    default_bid = DAILY_SALARY * 0.6
    if current_supply < WATER_REQ * 1.5 and num_alive_opponents > 1:
        default_bid = DAILY_SALARY * 0.7

    return min(my_status['budget'], default_bid)

